-- Catalog module (T-E1-01, UC-05 and UC-06). Public data without personal data: no Row Level Security (RNF-27).
-- Ids are UUIDs generated by the application; timestamps come from the injected Clock, so there are no defaults.
-- Stock is not here: it lives in the inventory module (stock_level, ARCHITECTURE.md section 12).

CREATE TABLE category (
    id         UUID                     NOT NULL,
    name       TEXT                     NOT NULL,
    slug       TEXT                     NOT NULL,
    position   INTEGER                  NOT NULL,
    active     BOOLEAN                  NOT NULL,
    created_at TIMESTAMP WITH TIME ZONE NOT NULL,
    updated_at TIMESTAMP WITH TIME ZONE NOT NULL,
    CONSTRAINT category_pk PRIMARY KEY (id),
    -- UC-05: the slug is unique; the application surfaces a violation as SlugAlreadyUsed.
    CONSTRAINT category_slug_uk UNIQUE (slug),
    CONSTRAINT category_name_length_ck CHECK (name = btrim(name) AND char_length(name) BETWEEN 1 AND 80),
    CONSTRAINT category_slug_format_ck CHECK (slug ~ '^[a-z0-9]+(-[a-z0-9]+)*$' AND char_length(slug) <= 100),
    CONSTRAINT category_position_ck CHECK (position >= 0)
);

CREATE TABLE product (
    id          UUID                     NOT NULL,
    category_id UUID                     NOT NULL,
    name        TEXT                     NOT NULL,
    slug        TEXT                     NOT NULL,
    description TEXT                     NOT NULL,
    material    TEXT                     NOT NULL,
    season      TEXT                     NOT NULL,
    audience    TEXT                     NOT NULL,
    -- Published (true) or hidden (false). A product is created hidden and published through UC-06.
    active      BOOLEAN                  NOT NULL,
    created_at  TIMESTAMP WITH TIME ZONE NOT NULL,
    updated_at  TIMESTAMP WITH TIME ZONE NOT NULL,
    CONSTRAINT product_pk PRIMARY KEY (id),
    -- UC-05: a category with products cannot be deleted, only deactivated.
    CONSTRAINT product_category_fk FOREIGN KEY (category_id) REFERENCES category (id) ON DELETE RESTRICT,
    CONSTRAINT product_slug_uk UNIQUE (slug),
    CONSTRAINT product_name_length_ck CHECK (name = btrim(name) AND char_length(name) BETWEEN 1 AND 120),
    CONSTRAINT product_slug_format_ck CHECK (slug ~ '^[a-z0-9]+(-[a-z0-9]+)*$' AND char_length(slug) <= 140),
    CONSTRAINT product_description_length_ck CHECK (char_length(description) <= 5000),
    CONSTRAINT product_material_length_ck CHECK (material = btrim(material) AND char_length(material) BETWEEN 1 AND 80),
    CONSTRAINT product_season_ck CHECK (season IN ('SUMMER', 'MID_SEASON', 'WINTER')),
    CONSTRAINT product_audience_ck CHECK (audience IN ('WOMEN', 'MEN', 'KIDS'))
);

-- E1 plan: listing by category of active products.
CREATE INDEX product_category_active_idx ON product (category_id, active);

CREATE TABLE variant (
    id             UUID                     NOT NULL,
    product_id     UUID                     NOT NULL,
    sku            TEXT                     NOT NULL,
    -- Sizes and colors are free text per product, shown in the order they were entered in the variant matrix.
    size           TEXT                     NOT NULL,
    size_position  INTEGER                  NOT NULL,
    color          TEXT                     NOT NULL,
    color_position INTEGER                  NOT NULL,
    -- Integer cents, ARS (R-01). Null until the administrator sets it; a product needs a priced variant to publish.
    price_cents    BIGINT,
    active         BOOLEAN                  NOT NULL,
    created_at     TIMESTAMP WITH TIME ZONE NOT NULL,
    updated_at     TIMESTAMP WITH TIME ZONE NOT NULL,
    CONSTRAINT variant_pk PRIMARY KEY (id),
    CONSTRAINT variant_product_fk FOREIGN KEY (product_id) REFERENCES product (id) ON DELETE RESTRICT,
    -- UC-06: the SKU is unique across the shop.
    CONSTRAINT variant_sku_uk UNIQUE (sku),
    -- Target of product_image's composite key: an image's variant belongs to the image's product.
    CONSTRAINT variant_id_product_uk UNIQUE (id, product_id),
    CONSTRAINT variant_sku_length_ck CHECK (sku = btrim(sku) AND char_length(sku) BETWEEN 1 AND 40),
    CONSTRAINT variant_size_length_ck CHECK (size = btrim(size) AND char_length(size) BETWEEN 1 AND 20),
    CONSTRAINT variant_color_length_ck CHECK (color = btrim(color) AND char_length(color) BETWEEN 1 AND 30),
    CONSTRAINT variant_positions_ck CHECK (size_position >= 0 AND color_position >= 0),
    CONSTRAINT variant_price_ck CHECK (price_cents > 0)
);

-- UC-06: no two variants of a product share size and color. Also serves the lookups by product (E1 plan: index on
-- variant(product_id)).
CREATE UNIQUE INDEX variant_product_size_color_uk ON variant (product_id, size, color);

CREATE TABLE product_image (
    id          UUID                     NOT NULL,
    product_id  UUID                     NOT NULL,
    -- Optional: the photo of one variant (the gallery follows the chosen variant, UC-03).
    variant_id  UUID,
    -- Server-generated base name of the stored WebP files under /uploads (RNF-29.4); never the uploaded file name.
    storage_key TEXT                     NOT NULL,
    -- Tiny blurred WebP as a data URI for the blur-up effect (E1 plan: 10 px).
    placeholder TEXT                     NOT NULL,
    position    INTEGER                  NOT NULL,
    created_at  TIMESTAMP WITH TIME ZONE NOT NULL,
    CONSTRAINT product_image_pk PRIMARY KEY (id),
    CONSTRAINT product_image_product_fk FOREIGN KEY (product_id) REFERENCES product (id) ON DELETE CASCADE,
    CONSTRAINT product_image_variant_fk FOREIGN KEY (variant_id, product_id)
        REFERENCES variant (id, product_id) ON DELETE CASCADE,
    CONSTRAINT product_image_storage_key_uk UNIQUE (storage_key),
    CONSTRAINT product_image_storage_key_format_ck CHECK (storage_key ~ '^[a-z0-9][a-z0-9-]{0,99}$'),
    -- Only base64 after the prefix: nothing that could break out of an HTML attribute or a CSS url().
    CONSTRAINT product_image_placeholder_ck CHECK (
        placeholder ~ '^data:image/webp;base64,[A-Za-z0-9+/]+={0,2}$' AND char_length(placeholder) <= 4000),
    CONSTRAINT product_image_position_ck CHECK (position >= 0)
);

CREATE INDEX product_image_product_idx ON product_image (product_id, position);
